exercises.solution:
def creer_fiche(titre, ville="Lomé", places=0):
    return {"titre": titre, "ville": ville, "places": places}


def catalogue(titres, options):
    resultat = []
    for titre in titres:
        resultat.append(creer_fiche(
            titre,
            places=options.get("places", 0),
            ville=options.get("ville", "Lomé"),
        ))
    return resultat
